             "1. Обдайте утку кипятком, обсушите, дайте коже подсохнуть несколько часов в холодильнике.\n2. Смажьте кожу смесью мёда и соевого соуса.\n3. Запекайте при 180°C около 1.5 часов до хрустящей корочки.\n4. Нарежьте утку тонкими ломтиками вместе с кожей.\n5. Подавайте с тонкими блинчиками, соломкой огурца, зелёным луком и соусом хойсин — заворачивая всё в блинчик.",
