             "1. Растопите мёд с сахаром и маслом на водяной бане, добавьте соду — масса вспенится.\n2. Снимите с огня, вмешайте яйца и муку до однородного теста.\n3. Разделите тесто на части, раскатайте тонкие коржи, выпекайте по 5-7 минут при 180°C.\n4. Взбейте сметану с сахаром для крема.\n5. Промажьте каждый корж кремом, соберите торт.\n6. Дайте пропитаться в холодильнике минимум 6 часов.",
