             "1. Смешайте фарш с мелко нарезанным луком и специями.\n2. Раскатайте тесто тонко, нарежьте небольшими квадратами.\n3. Положите начинку, слепите маленькие пельмешки узелком.\n4. Отварите чучвару в кипящем бульоне 5-7 минут.\n5. Подавайте в бульоне со сметаной и зеленью.",
