             "конина или говядина|тесто пресное|лук|чёрный перец|бульон",
             "1. Отварите мясо до мягкости несколько часов, остудите в бульоне.\n2. Нарежьте отварное мясо тончайшей соломкой.\n3. Раскатайте и отварите тонкие полоски пресного теста.\n4. Тонко нашинкуйте лук, ошпарьте кипятком.\n5. Смешайте мясо, тесто и лук, приправьте перцем, подавайте с бульоном.",
