             "1. Замесите крутое тесто из муки, яиц, сахара и сметаны.\n2. Дайте тесту отдохнуть 20 минут под плёнкой.\n3. Раскатайте тонко, нарежьте полосками, сделайте надрез и протяните конец полоски в него (бантик).\n4. Обжарьте во фритюре до золотистого цвета.\n5. Обсыпьте сахарной пудрой перед подачей.",
