             "", "",
             "курица|оливки|лимон маринованный|лук|имбирь|куркума|шафран|кинза",
             "1. Обжарьте куски курицы до румяной корочки.\n2. Добавьте лук, имбирь, куркуму и шафран, обжарьте до аромата.\n3. Влейте немного воды, тушите под крышкой 40 минут.\n4. Добавьте оливки и маринованный лимон, тушите ещё 10 минут.\n5. Посыпьте свежей кинзой перед подачей.",
