             "треска солёная|картофель соломкой|лук|яйца|маслины|петрушка",
             "1. Вымочите солёную треску в воде 24 часа, меняя воду, затем отварите и разберите на волокна.\n2. Обжарьте лук до мягкости, добавьте треску, обжарьте вместе 5 минут.\n3. Добавьте картофель соломкой (можно готовый, обжаренный отдельно).\n4. Влейте взбитые яйца, готовьте, помешивая, до кремовой консистенции (не пересушивая).\n5. Посыпьте петрушкой и маслинами перед подачей.",
