             "рис круглозёрный|молоко|сахар|яичные желтки|цедра лимона|корица",
             "1. Отварите рис в подсоленной воде 5 минут, слейте воду.\n2. Залейте рис молоком с цедрой лимона, варите на слабом огне 20 минут до мягкости.\n3. Добавьте сахар, перемешайте.\n4. Смешайте немного горячего риса с желтками, верните в кастрюлю, прогрейте не доводя до кипения.\n5. Разложите по формочкам, посыпьте корицей узором, охладите перед подачей.",
