             "1. Разотрите холодное масло с мукой, сахаром и разрыхлителем в крошку.\n2. Влейте молоко, быстро замесите мягкое тесто, не перемешивая слишком долго.\n3. Раскатайте пласт толщиной 2-3 см, вырежьте кружки стаканом.\n4. Выпекайте при 220°C 12-15 минут до золотистого верха.\n5. Разрежьте тёплые сконы пополам, подавайте с джемом и взбитыми сливками.",
