             "рис|помидоры|болгарский перец|лук|перец чили|курица|томатная паста|карри порошок",
             "1. Пробейте блендером помидоры, перец и лук до пюре.\n2. Обжарьте томатное пюре с томатной пастой 15 минут до загустения.\n3. Добавьте специи и бульон, доведите до кипения.\n4. Всыпьте рис, готовьте под крышкой на слабом огне 25-30 минут.\n5. Подавайте с обжаренной отдельно курицей.",
