             "1. Отварите баранину до мягкости, бульон сохраните.\n2. Обжарьте морковь соломкой с изюмом до карамелизации, отложите.\n3. Обжарьте лук с мясом до румяной корочки.\n4. Отварите рис до полуготовности в бульоне со специями.\n5. Выложите слоями рис и мясо в казан, сверху морковь с изюмом, томите на пару 30 минут.",
