             "молодой кокос (мякоть и вода)|лёд|сахар по желанию",
             "1. Слейте кокосовую воду из молодого кокоса в стакан.\n2. Достаньте мягкую мякоть ложкой, добавьте в стакан.\n3. Добавьте лёд.\n4. Подсластите сахаром по желанию.\n5. Перемешайте и подавайте сразу охлаждённым.",
