             "картофель жёлтый|перец ахи амарильо|лимон|курица варёная|майонез|авокадо",
             "1. Отварите и разомните картофель в пюре с перцем ахи и лимонным соком.\n2. Разделите пюре на порции, сформируйте лепёшки.\n3. Смешайте курицу с майонезом для начинки.\n4. Выложите начинку между двумя слоями картофельного пюре.\n5. Украсьте авокадо и майонезом сверху.",
