             "лапша стеклянная|говядина|шпинат|морковь|грибы|соевый соус|кунжутное масло",
             "1. Отварите стеклянную лапшу, промойте.\n2. Обжарьте говядину полосками.\n3. Обжарьте овощи отдельно каждый.\n4. Смешайте лапшу с мясом и овощами.\n5. Заправьте соевым соусом и кунжутным маслом.",
