             "курица|арахис|перец чили сухой|соевый соус|уксус рисовый|чеснок|имбирь",
             "1. Нарежьте курицу кубиками, замаринуйте в соевом соусе.\n2. Обжарьте сухой чили и арахис на масле.\n3. Добавьте курицу, обжарьте до готовности.\n4. Добавьте чеснок и имбирь.\n5. Заправьте соусом из соевого соуса и уксуса, обжарьте ещё минуту.",
