             "1. Обжарьте фарш с доубаньцзян и сычуаньским перцем.\n2. Смешайте кунжутную пасту с соевым соусом и чесноком для основы.\n3. Отварите лапшу.\n4. Выложите лапшу в соусную основу.\n5. Положите обжаренный фарш сверху, посыпьте зелёным луком.",
