             "макароны|сыр чеддер|молоко|масло сливочное|мука|панировочные сухари",
             "1. Отварите макароны до готовности.\n2. Приготовьте соус бешамель из масла, муки и молока.\n3. Добавьте тёртый сыр, помешивайте до расплавления.\n4. Смешайте макароны с сырным соусом.\n5. Посыпьте сухарями, запеките при 190°C 15-20 минут до румяной корочки.",
