             "1. Смешайте кукурузную и пшеничную муку с разрыхлителем и сахаром.\n2. Добавьте яйцо, молоко и растопленное масло.\n3. Перемешайте до однородности, не перебивая тесто.\n4. Вылейте в форму.\n5. Выпекайте при 200°C 20-25 минут до золотистой корочки.",
